const updateStatusValidator = (req: Request, res: Response, next: NextFunction) => {
  checkSchema({
    shipmentId: {
      in: ['params'],
      isMongoId: true,
      errorMessage: 'Shipment ID must be a valid MongoDB ID',
    },
    status: {
      in: ['body'],
      isString: true,
      notEmpty: true,
      isIn: {
        options: [Array.from(MODEL_STATUSES)],
        errorMessage: 'Status must be one of: In-Warehouse, Shipped, Dispatched, Delivered, Returned, Failed',
      },
    },
    note: { in: ['body'], optional: true, isString: true },
  });
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

