const statusFilterValidator = (req: Request, res: Response, next: NextFunction) => {
  checkSchema({
    status: {
      in: ['params'],
      isString: true,
      notEmpty: true,
      isIn: {
        options: [Array.from(MODEL_STATUSES)],
        errorMessage: 'Status must be one of: In-Warehouse, Shipped, Dispatched, Delivered, Returned, Failed',
      },
    },
  });
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

const bulkUpdateValidator = (req: Request, res: Response, next: NextFunction) => {
  checkSchema({
    shipmentIds: {
      in: ['body'],
      isArray: {
        options: { min: 1 },
        errorMessage: 'shipmentIds must be an array with at least one ID',
      },
    },
    'shipmentIds.*': {
      in: ['body'],
      isMongoId: true,
      errorMessage: 'Each shipment ID must be a valid MongoDB ID',
    },
    status: {
      in: ['body'],
      isString: true,
      notEmpty: true,
      isIn: {
        options: [Array.from(MODEL_STATUSES)],
        errorMessage: 'Status must be one of: In-Warehouse, Shipped, Dispatched, Delivered, Returned, Failed',
      },
    },
    note: { in: ['body'], optional: true, isString: true },
  });
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

const ShipmentValidator = {
  createShipmentValidator,
  updateShipmentValidator,
  shipmentIdValidator,
  updateStatusValidator,
  addTrackingValidator,
  statusFilterValidator,
  bulkUpdateValidator,
};

export default ShipmentValidator;
